import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const p="/assets/%E9%80%9A%E4%BF%A1%E4%BB%BB%E5%8A%A1%E9%87%8D%E6%89%A7%E8%A1%8C%E6%9C%BA%E5%88%B6.CZ5qdVpu.png",u=JSON.parse('{"title":"特性场景","description":"","frontmatter":{},"headers":[{"level":1,"title":"特性场景","slug":"特性场景"},{"level":2,"title":"重执行","slug":"重执行"}],"relativePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/特性场景.md","filePath":"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/特性场景.md"}'),i={name:"guide/算子实践参考/SIMD算子实现/融合算子编程/通算融合/特性场景.md"};function l(r,e,o,c,d,_){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="特性场景" tabindex="-1">特性场景 <a class="header-anchor" href="#特性场景" aria-label="Permalink to &quot;特性场景&quot;">​</a></h1><h2 id="重执行" tabindex="-1">重执行 <a class="header-anchor" href="#重执行" aria-label="Permalink to &quot;重执行&quot;">​</a></h2><p>为避免执行通信任务的环境中硬件闪断导致发生通信中断，通算融合算子可通过配置编译宏与环境变量，开启重执行能力。通算融合算子开启重执行后，AI CPU在检测到环境异常时，通过下图示意的机制，通知AI Core重新下发通信任务，避免由于硬件闪断造成的通信中断，提升通信稳定性。</p><p>当前，该能力的支持情况如下：</p><p>Ascend 950PR/Ascend 950DT不支持通算融合算子的重执行。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持通算融合算子的重执行。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品支持通算融合算子的重执行。</p><p><strong>图 1</strong> 通信任务重执行机制<br><img src="'+p+`" alt="" title="通信任务重执行机制"></p><p>开启重执行的条件如下：</p><ul><li><p>通算融合算子的输出内存地址和输入内存地址不相同。</p></li><li><p>通算融合算子仅存在Server间通信（Server为计算节点，通常是8卡或16卡的昇腾NPU设备组成的服务器形态的统称）。</p></li><li><p>算子编译时，配置编译宏AICORE_EXCEPTION_RESTART，如下所示。具体的编译宏配置阶段和方式请参考<a href="./../../../../编程指南/附录/工程化算子开发/算子包编译/算子工程编译.html#section7321165972311">支持自定义编译选项</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ops_compile_options(ALL OPTIONS -DAICORE_EXCEPTION_RESTART)</span></span></code></pre></div></li><li><p>配置HCCL重执行环境变量HCCL_OP_RETRY_ENABLE，开启重执行的检测和上报能力，该环境变量的说明请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityEnvRef" target="_blank" rel="noreferrer">《环境变量参考》</a>“集合通信 &gt; 可靠性相关 &gt; HCCL_OP_RETRY_ENABLE”。请在算子执行前设置该环境变量，具体配置如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># server间L1需配置为1, 不支持跨超节点，L2配置为0。</span></span>
<span class="line"><span>export HCCL_OP_RETRY_ENABLE=&quot;L1:1, L2:0&quot;</span></span></code></pre></div><p>注意，开启重执行后，若AI Core第一次下发通信任务后通信中断，默认只重执行一次。若需修改重执行次数或重传间隔时间，请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityEnvRef" target="_blank" rel="noreferrer">《环境变量参考》</a>“集合通信 &gt; 可靠性相关 &gt; HCCL_OP_RETRY_PARAMS”。</p></li></ul>`,10)])])}const A=a(i,[["render",l]]);export{u as __pageData,A as default};
